"""Subagents: a `task` tool that runs a child agent loop with a fresh context.

The child gets the parent's tools (minus `task`, so it cannot recurse), permissions and
hooks, but none of the parent's messages. Only its final summary comes back, so a
reading-heavy job costs the parent a paragraph instead of every file the child read.
"""
from __future__ import annotations

from .tools import Tool

SUBAGENT_PROMPT = """You are a subagent of nanoharness. You were given one focused task by the main agent.
Do it with your tools, then reply with a concise report: what you found or changed, with file
paths and line numbers. The main agent sees only that final reply, not your tool calls."""


def run_subagent(parent, description: str, prompt: str) -> str:
    """Part 9: Run `prompt` in a child Agent and return its report.

    The child: model = parent.subagent_model or parent.model; tools = parent.tools without
    "task"; system = SUBAGENT_PROMPT + "\\n\\n" + parent.system; the parent's permissions and
    hooks; max_turns = parent.subagent_max_turns; no session; a fresh transcript.
    Add the child's usage to parent.child_usage. Return
    f"[subagent: {description}; {turns} turns]\\n{final_text}" (or a note if it hit max_turns).
    """
    raise NotImplementedError("Part 9: implement run_subagent (see the docstring)")


def make_task_tool(parent) -> Tool:
    return Tool(
        "task",
        "Hand a focused, self-contained job to a subagent with a fresh context, e.g. 'find where X is "
        "defined and how it is used'. It has your tools and returns only a short report. Use it for "
        "searches and reading that would otherwise fill your context. The prompt must stand alone: "
        "the subagent cannot see this conversation.",
        {"type": "object", "properties": {"description": {"type": "string"}, "prompt": {"type": "string"}},
         "required": ["description", "prompt"]},
        lambda description, prompt: run_subagent(parent, description, prompt),
    )
